// Storage Key Hierarchy: faculties -> courses/departments -> core academic area -> book file

import { getSupabaseBookUrl } from '../config/supabaseConfig'

export interface BookMetadata {
  id: string
  title: string
  author: string
  extraMeta: string // volume, edition, publication, chapter info
  faculty: string
  department: string
  coreArea: string
  fileName: string
  fileUrl: string
  fileExtension: string
  coverUrl: string
  publishedYear?: string
  description?: string
  storagePath: string
}

export interface BookEntryDefinition {
  faculty: string
  department: string
  coreArea: string
  fileName: string
  storagePath: string
  title: string
  author: string
  extraMeta: string
  publishedYear?: string
  description?: string
  coverFallbackUrl: string
}

